--
-- Table structure for table `calibration_workbook_data`
--

DROP TABLE IF EXISTS `calibration_workbook_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `calibration_workbook_data` (
  `id` varchar(255) NOT NULL,
  `task_id` varchar(255) NOT NULL COMMENT '任务ID（任务id和templatecode相等那就是模板工作簿，可被多任务共享）',
  `workbook_data` longblob COMMENT '工作簿二进制数据',
  `template_code` varchar(255) NOT NULL COMMENT '模板代码',
  `update_by` varchar(100) DEFAULT NULL COMMENT '最后更新用户',
  `last_access_time` timestamp NULL DEFAULT NULL COMMENT '最后访问时间戳',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_active` tinyint(4) DEFAULT '1' COMMENT '是否活跃：1-活跃，0-已清理',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_id` (`task_id`),
  KEY `idx_is_active` (`is_active`) USING BTREE,
  KEY `idx_last_access_time` (`last_access_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='工作簿数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

