DROP TABLE IF EXISTS `excel_data_asset`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `excel_data_asset` (
  `id` varchar(100) NOT NULL COMMENT '主键ID',
  `template_code` varchar(50) NOT NULL COMMENT '关联模板编码',
  `batch_no` varchar(50) NOT NULL COMMENT '导入批次号',
  `structured_data` json NOT NULL COMMENT '结构化数据(按模板配置存储)',
  `import_status` varchar(20) DEFAULT 'SUCCESS' COMMENT '导入状态:SUCCESS/FAILED',
  `create_user` varchar(100) DEFAULT NULL,
  `update_user` varchar(100) DEFAULT NULL,
  `create_time` timestamp NULL DEFAULT NULL,
  `update_time` timestamp NULL DEFAULT NULL,
  `measured` varchar(100) DEFAULT '0' COMMENT '未检测0，检测成功1，检测失败2',
  `check_result` varchar(100) DEFAULT '0' COMMENT '未检测0，合格1，不合格2',
  PRIMARY KEY (`id`),
  KEY `idx_template_code` (`template_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Excel数据资产表';
/*!40101 SET character_set_client = @saved_cs_client */;

