--
-- Table structure for table `excel_template`
--

DROP TABLE IF EXISTS `excel_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `excel_template` (
  `id` varchar(100) NOT NULL COMMENT '主键ID',
  `template_code` varchar(50) NOT NULL COMMENT '模板编码(唯一标识)',
  `template_name` varchar(100) NOT NULL COMMENT '模板名称',
  `column_config` json NOT NULL COMMENT '列配置信息[{"fieldName":"姓名","excelHeader":"姓名","dataType":"STRING"}]',
  `status` tinyint(4) DEFAULT '1' COMMENT '状态:0-禁用,1-启用',
  `create_user` varchar(100) DEFAULT NULL,
  `update_user` varchar(100) DEFAULT NULL,
  `create_time` timestamp NULL DEFAULT NULL,
  `update_time` timestamp NULL DEFAULT NULL,
  `model` varchar(100) CHARACTER SET utf8 DEFAULT NULL COMMENT '适用于哪个型号的仪器',
  `applicable_countries` varchar(100) CHARACTER SET utf8 DEFAULT NULL COMMENT '适用国家',
  `category` varchar(255) CHARACTER SET utf8 DEFAULT '0' COMMENT '内置模板0其他模板1',
  `last_used` timestamp NULL DEFAULT NULL COMMENT '最近一次使用时间',
  `remark` text CHARACTER SET utf8 COMMENT '模板描述',
  `parent_id` varchar(100) DEFAULT NULL COMMENT '父模板id',
  `use_count` int(11) DEFAULT '0' COMMENT '使用次数',
  PRIMARY KEY (`id`),
  UNIQUE KEY `template_code` (`template_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Excel模板配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `excel_template`
--

