--
-- Table structure for table `task_management`
--

DROP TABLE IF EXISTS `task_management`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_management` (
  `id` varchar(100) NOT NULL COMMENT '任务唯一标识，主键，自增长',
  `detect_name` varchar(255) NOT NULL COMMENT '检测任务名称，必填项',
  `operation_instrument` varchar(100) DEFAULT NULL COMMENT '执行此任务所使用的操作仪器，可为空',
  `use_template` varchar(100) DEFAULT NULL COMMENT '任务所使用的模板名称或编号，可为空',
  `content_category` varchar(50) DEFAULT NULL COMMENT '任务内容的分类，可为空',
  `start_time` datetime DEFAULT NULL COMMENT '任务的计划或实际开始时间，可为空',
  `completion_status` varchar(10) DEFAULT NULL COMMENT '任务的完成状态枚举：未开始0、未完成1、已完成2',
  `completion_time` datetime DEFAULT NULL COMMENT '任务的实际完成时间，可为空',
  `create_user` varchar(100) NOT NULL COMMENT '记录创建者的用户ID，通常关联用户表',
  `update_user` varchar(100) DEFAULT NULL COMMENT '记录最后更新者的用户ID，通常关联用户表',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间，自动生成',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录最后更新时间，自动更新',
  `result_template` varchar(100) DEFAULT NULL COMMENT '结果模板的 id',
  `task_type` varchar(50) DEFAULT '1' COMMENT '任务类型1检定校准；2开箱验证；3出厂检验',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='任务管理表';
